  function lookup(source,language){
    if(labels[source]?.[language])return labels[source][language];
    const match=String(source).match(/^Under this agreement, Party A shall pay Party B, the individual commission recipient, a fixed commission of (.*?) for sales contract (.*?)\. No percentage-based or cumulative commission applies\.$/s);
    if(match&&labels[fixedCommission]?.[language])return labels[fixedCommission][language].replace('{amount}',()=>match[1]).replace('{contract}',()=>match[2]);
    const commissionRange=String(source).match(/^The indicative commission range is (.*?)%-(.*?)%\. The final rate must be confirmed in writing for each order\.$/s);
    if(commissionRange&&labels[range]?.[language])return labels[range][language].replace('{min}',()=>commissionRange[1]).replace('{max}',()=>commissionRange[2]);
    const pay=String(source).match(/^Payment: (.*?); settlement: (.*?) after all conditions are met\.$/s);
    if(pay&&labels[payment]?.[language])return labels[payment][language].replace('{payment}',()=>pay[1]).replace('{settlement}',()=>pay[2]);
    return '';
  }
  return {languages,labels,lookup,add};
